        if (*p > 63) {
                uint16_t offset;

                offset = p[1];
                offset += ((*p & ~0xc0) << 8);

                p = buf + offset;
        }

        /*
         *      Tell the caller where the actual label is located.
         */
        *start = p;
        *next = p + *p + 1;
        return *p;
